import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq/faq.md","filePath":"faq/faq.md"}'),n={name:"faq/faq.md"};function i(s,e,l,d,h,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="stylesheet-is-missing-or-theme-installation-fails" tabindex="-1">Stylesheet is missing or theme installation fails <a class="header-anchor" href="#stylesheet-is-missing-or-theme-installation-fails" aria-label="Permalink to &quot;Stylesheet is missing or theme installation fails&quot;">​</a></h2><p>Be sure to upload only the theme zip file, not the full downloaded package from ThemeForest. If the issue persists, check your <a href="./../general/server-requirements.html">Server Requirements</a>. <a href="./../troubleshooting/stylesheet-missing.html">Read more →</a></p><h2 id="where-can-i-find-my-purchase-code" tabindex="-1">Where can I find my purchase code? <a class="header-anchor" href="#where-can-i-find-my-purchase-code" aria-label="Permalink to &quot;Where can I find my purchase code?&quot;">​</a></h2><ul><li>After purchaseing your theme on <a href="https://wolfthemes.com" target="_blank" rel="noreferrer">WolfThemes.com</a>, you will received by email direclty in your inbox</li><li>In your <a href="https://themeforest.net/downloads" target="_blank" rel="noreferrer">ThemeForest Downloads</a>, click the <strong>Download</strong> button next to your theme and select <strong>License certificate &amp; purchase code (text)</strong>.</li></ul><h2 id="my-video-background-doesn-t-work-on-mobile" tabindex="-1">My video background doesn&#39;t work on mobile <a class="header-anchor" href="#my-video-background-doesn-t-work-on-mobile" aria-label="Permalink to &quot;My video background doesn&#39;t work on mobile&quot;">​</a></h2><p>Video backgrounds are disabled on mobile by default as most devices don&#39;t handle them well. You can set a fallback image in the video background options — it will display when the video is disabled.</p><h2 id="_404-error-on-custom-post-type-pages" tabindex="-1">404 error on custom post type pages <a class="header-anchor" href="#_404-error-on-custom-post-type-pages" aria-label="Permalink to &quot;404 error on custom post type pages&quot;">​</a></h2><p>Go to <strong>Settings &gt; Permalinks</strong> and click <strong>Save Changes</strong> to flush rewrite rules. <a href="./../troubleshooting/404-error.html">Read more →</a></p><h2 id="demo-content-fails-to-import" tabindex="-1">Demo content fails to import <a class="header-anchor" href="#demo-content-fails-to-import" aria-label="Permalink to &quot;Demo content fails to import&quot;">​</a></h2><p>Check your <a href="./../general/server-requirements.html">Server Requirements</a> — particularly <code>memory_limit</code>, <code>max_execution_time</code> and <code>upload_max_filesize</code>. If the one-click import fails, use the <a href="./../getting-started/import-demo-content-manually.html">manual import</a> instead. <a href="./../troubleshooting/issue-importing-demo.html">Read more →</a></p><h2 id="do-i-need-to-activate-bundled-plugins" tabindex="-1">Do I need to activate bundled plugins? <a class="header-anchor" href="#do-i-need-to-activate-bundled-plugins" aria-label="Permalink to &quot;Do I need to activate bundled plugins?&quot;">​</a></h2><p>No. Bundled plugins like WPBakery Page Builder and Slider Revolution work without activation. You can safely ignore any purchase code requests from these plugins. <a href="./../getting-started/bundled-plugin-activation.html">Read more →</a></p><h2 id="my-fonts-or-icons-are-not-displaying-correctly" tabindex="-1">My fonts or icons are not displaying correctly <a class="header-anchor" href="#my-fonts-or-icons-are-not-displaying-correctly" aria-label="Permalink to &quot;My fonts or icons are not displaying correctly&quot;">​</a></h2><p>Check that Elementor&#39;s default fonts are disabled under <strong>Elementor &gt; Settings &gt; General</strong> and that the CSS Print Method is set to <strong>Internal Embedding</strong> under <strong>Elementor &gt; Settings &gt; Performance</strong>. <a href="./../troubleshooting/elementor-settings.html">Read more →</a></p><h2 id="how-do-i-update-my-theme" tabindex="-1">How do I update my theme? <a class="header-anchor" href="#how-do-i-update-my-theme" aria-label="Permalink to &quot;How do I update my theme?&quot;">​</a></h2><p>Use the <a href="https://github.com/envato/wp-envato-market" target="_blank" rel="noreferrer">Envato Market plugin</a> for automatic updates, or download the latest package from ThemeForest and re-upload manually. <a href="./../how-to/themeforest-theme-update.html">Read more →</a></p><h2 id="my-site-is-slow-—-how-do-i-speed-it-up" tabindex="-1">My site is slow — how do I speed it up? <a class="header-anchor" href="#my-site-is-slow-—-how-do-i-speed-it-up" aria-label="Permalink to &quot;My site is slow — how do I speed it up?&quot;">​</a></h2><p>Make sure you are on a <a href="./../general/recommended-web-hosts.html">reliable host</a> and install EWWW Image Optimizer, WP Super Cache and Autoptimize. <a href="./../how-to/increase-loading-speed.html">Read more →</a></p><h2 id="how-do-i-translate-my-theme" tabindex="-1">How do I translate my theme? <a class="header-anchor" href="#how-do-i-translate-my-theme" aria-label="Permalink to &quot;How do I translate my theme?&quot;">​</a></h2><p>Use the <a href="https://wordpress.org/plugins/loco-translate/" target="_blank" rel="noreferrer">Loco Translate</a> plugin to translate directly in your WordPress admin using the <code>.pot</code> file included in the theme package. <a href="./../how-to/translate-theme.html">Read more →</a></p>',21)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
